let svg = {|<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect x="0" y="0" width="5" height="10" fill="#00ff00"/></svg>|}

let run () =
  let ok = ref true in
  let check name cond =
    Printf.printf "ariadne: imaged: %-40s %s\n%!" name (if cond then "ok" else "FAIL");
    if not cond then ok := false in
  let images = Images.connect () in
  let shape (rs : Ipc.request_doc list) =
    List.map (fun (r : Ipc.request_doc) -> (r.case, r.name, r.args, r.reply, r.safe)) rs in
  let d = Ipc.describe "image" in
  check "described as images.ml says"
    (d.Ipc.protocol = Images.Protocol.id && shape d.requests = shape Images.Protocol.requests);
  (* a pixel: red, green, blue, alpha *)
  let px (p : Images.picture) x y =
    let o = (y * p.image.Gfx.image_width + x) * 4 and b = p.image.bgra in
    let c k = Char.code b.[o + k] in
    (c 2, c 1, c 0, c 3) in
  let near (r, g, b, a) (r', g', b', a') t = abs (r - r') <= t && abs (g - g') <= t && abs (b - b') <= t && a = a' in
  let p = Images.decode ~images png in
  check "PNG: its size" (p.natural_width = 4 && p.natural_height = 2 && p.image.image_width = 4);
  check "PNG: red, green, blue, transparent"
    (px p 0 0 = (255, 0, 0, 255) && px p 1 0 = (0, 255, 0, 255) && px p 2 0 = (0, 0, 255, 255)
     && (let _, _, _, a = px p 3 0 in a = 0));
  check "PNG: half transparent, and colours" (px p 0 1 = (255, 255, 255, 128) && px p 3 1 = (1, 2, 3, 255));
  check "PNG: its size alone" (Images.size ~images png = (4, 2));
  let j = Images.decode ~images jpeg in
  check "JPEG: its size, its colour"
    (j.natural_width = 16 && near (px j 8 8) (200, 40, 40, 255) 6 && near (px j 0 15) (200, 40, 40, 255) 6);
  let j2 = Images.decode ~images ~width:4 ~height:4 jpeg in
  check "JPEG: scaled to 4 x 4" (j2.image.image_width = 4 && j2.image.image_height = 4
                                  && near (px j2 2 2) (200, 40, 40, 255) 6);
  let s = Images.decode ~images ~width:20 ~height:20 svg in
  check "SVG: drawn at 20 x 20, its own size 10 x 10"
    (s.natural_width = 10 && s.image.image_width = 20 && near (px s 4 10) (0, 255, 0, 255) 2
     && (let _, _, _, a = px s 15 10 in a = 0));
  check "not a picture: an error"
    (match Images.decode ~images "not a picture" with _ -> false | exception Ipc.Remote_error _ -> true);
  print_endline (if !ok then "ariadne: imaged: all checks passed" else "ariadne: imaged: FAIL");
  if not !ok then exit 1
